// Signs the call to Convex with LENDLOOP_API_SECRET (from the environment).
const crypto = require('crypto');
const secret = ($env.LENDLOOP_API_SECRET || '').split(',')[0].trim();
if (!secret) throw new Error('LENDLOOP_API_SECRET is not set');
const body = '{}';
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return [{ json: { body, timestamp, signature } }];

// One item per overdue loan (Convex already left out loans reminded today). Zero loans = run ends quietly.
const { loans = [] } = $input.first().json;
const appUrl = ($env.LENDLOOP_APP_URL || 'http://localhost:3100').replace(/\/$/, '');
const from = $env.NOTIFY_FROM || 'LendLoop <onboarding@resend.dev>';
const override = ($env.NOTIFY_OVERRIDE_TO || '').trim();
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = iso => new Date(iso + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });

return loans.map(l => {
  const days = l.daysOverdue === 1 ? '1 day' : `${l.daysOverdue} days`;
  const subject = `Reminder: please return the ${l.toolName}`;
  const line = `The ${l.toolName} you borrowed from ${l.lenderName} was due back on ${fmt(l.endDate)} (${days} ago).`;
  const html = `<div style="font-family:system-ui,sans-serif;max-width:520px;color:#18181b">` +
    (override ? `<p style="font-size:12px;color:#6b6b74">Dev mode: intended for ${esc(l.borrower.email)}</p>` : '') +
    `<p>Hi ${esc(l.borrower.name)},</p><p>${esc(line)}</p><p>Could you arrange to drop it back? ${esc(l.lenderName)} will mark it returned once they have it.</p>` +
    `<p><a href="${appUrl}/requests" style="display:inline-block;background:#18181b;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none">See your loan</a></p>` +
    `<p style="font-size:12px;color:#6b6b74">LendLoop. You'll get one reminder a day until it's returned.</p></div>`;
  return { json: {
    loanId: l.loanId,
    reminderKey: l.reminderKey,
    resend: {
      from,
      to: [override || l.borrower.email],
      subject: override ? `[for ${l.borrower.email}] ${subject}` : subject,
      html,
      text: `Hi ${l.borrower.name},\n\n${line}\n\nSee your loan: ${appUrl}/requests`,
    },
  } };
});

// The reminderKey (loan + date) is the idempotency key: re-sending this write-back can't create a second record.
const crypto = require('crypto');
const secret = ($env.LENDLOOP_API_SECRET || '').split(',')[0].trim();
if (!secret) throw new Error('LENDLOOP_API_SECRET is not set');
const src = $('Build reminder emails').item.json;
const body = JSON.stringify({ loanId: src.loanId, kind: 'reminder_sent', idempotencyKey: src.reminderKey });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature } };

// A failure gets its own key (per execution), so it doesn't block a retry of the reminder later today.
const crypto = require('crypto');
const secret = ($env.LENDLOOP_API_SECRET || '').split(',')[0].trim();
if (!secret) throw new Error('LENDLOOP_API_SECRET is not set');
const src = $('Build reminder emails').item.json;
const body = JSON.stringify({ loanId: src.loanId, kind: 'reminder_failed', idempotencyKey: `${src.reminderKey}:failed:${$execution.id}`, detail: 'email provider error' });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature, error: $json.error?.message || 'Resend request failed' } };
